// Booking Service: handles reservation creation with calendar conflict checks
var builder = WebApplication.CreateBuilder(args);

builder.Services.AddDbContext<BookingDbContext>(opt =>
    opt.UseSqlServer(builder.Configuration.GetConnectionString("BookingDb"))
);
builder.Services.AddStackExchangeRedisCache(opt =>
    opt.Configuration = builder.Configuration.GetConnectionString("Redis")
);
// Idempotency key ensures duplicate booking requests do not create duplicates
builder.Services.AddHttpContextAccessor();

var app = builder.Build();

app.MapPost("/bookings", async (CreateBookingRequest req, BookingDbContext db) => {
    // 1. Check calendar availability (pessimistic lock or advisory)
    var conflicts = await db.Bookings
        .AnyAsync(b => b.ListingId == req.ListingId &&
            b.Status != BookingStatus.Cancelled &&
            b.CheckIn < req.CheckOut && b.CheckOut > req.CheckIn);
    if (conflicts) return Results.Conflict("Dates not available");

    var booking = new Booking
    {
        Id = Guid.NewGuid(),
        ListingId = req.ListingId,
        GuestId = req.GuestId,
        CheckIn = req.CheckIn,
        CheckOut = req.CheckOut,
        TotalPrice = req.TotalPrice,
        Status = BookingStatus.Pending
    };
    db.Bookings.Add(booking);
    await db.SaveChangesAsync();

    // 2. Publish event for payment and notification services
    await bus.Publish(new BookingCreatedEvent(booking.Id, booking.ListingId));
    return Results.Created($"/bookings/{booking.Id}", booking);
})
.WithName("CreateBooking");

app.MapGet("/health", () => Results.Ok());
app.Run();
